    for path, size in find_large_files(directory):
        print(f"{size:8.1f} MB  {path}")

import pytest

def add(a, b):
    """Add two numbers."""
    return a + b

class TestAdd:
    """Comprehensive tests for the add function."""

    def test_positive_integers(self):
        assert add(2, 3) == 5

    def test_negative_integers(self):
        assert add(-1, -1) == -2

    def test_mixed_sign(self):
        assert add(-1, 1) == 0

    def test_zero(self):
        assert add(0, 5) == 5
        assert add(0, 0) == 0

    def test_floats(self):
        assert add(0.1, 0.2) == pytest.approx(0.3)

    def test_string_concatenation(self):
        assert add("hello", " world") == "hello world"

    def test_type_error(self):
        with pytest.raises(TypeError):
            add("a", 1)

from fastapi import FastAPI, HTTPException
from pydantic import BaseModel
from typing import List

app = FastAPI()

class Item(BaseModel):
    name: str
    price: float
    in_stock: bool = True

items: dict[int, Item] = {}
next_id = 0

@app.get("/items")
def list_items() -> List[dict]:
    return [{"id": k, **v.model_dump()} for k, v in items.items()]

@app.get("/items/{item_id}")
def get_item(item_id: int):
    if item_id not in items:
        raise HTTPException(404, "Item not found")
    return {"id": item_id, **items[item_id].model_dump()}

@app.post("/items")
def create_item(item: Item):
    global next_id
    items[next_id] = item
    next_id += 1
    return {"id": next_id - 1, **item.model_dump()}

@app.delete("/items/{item_id}")
def delete_item(item_id: int):
    if item_id not in items:
        raise HTTPException(404, "Item not found")
    del items[item_id]
    return {"deleted": True}

import csv
from collections import Counter
from pathlib import Path

def analyze_csv(filepath):
    """Read CSV and return summary statistics."""
    with open(filepath, newline='', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        rows = list(reader)

    if not rows:
        return {"error": "Empty CSV"}

    columns = list(rows[0].keys())
    stats = {"rows": len(rows), "columns": columns, "numeric_stats": {}}

    for col in columns:
        values = [row[col] for row in rows]
        try:
            nums = [float(v) for v in values if v]
            if nums:
                stats["numeric_stats"][col] = {
                    "mean": sum(nums) / len(nums),
                    "min": min(nums),
                    "max": max(nums),
                    "count": len(nums),
                }
        except ValueError:
            freq = Counter(values)
            stats["numeric_stats"][col] = {"unique": len(freq), "top": freq.most_common(3)}

    return stats
